async function main(ctx) {
  const response = ctx.input?.body || {};
  const elements = response.elements || [];

  if (elements.length === 0) {
    throw new Error('Organization not found');
  }

  const org = elements[0];
  const orgId = org.id;

  if (!orgId) {
    throw new Error('Could not extract organization ID');
  }

  const authorUrn = 'urn:li:organization:' + orgId;
  const initialArgs = ctx.lastOutputOf('__initial__') || {};

  return {
    author: authorUrn,
    count: initialArgs.count || 10,
    start: initialArgs.start || 0,
    organizationName: org.localizedName || org.name || 'Unknown',
    organizationId: orgId
  };
}

async function main(ctx) {
  const response = ctx.input?.body || {};
  const elements = response.elements || [];
  const orgData = ctx.lastOutputOf('extract_org_id') || {};

  // Transform posts to include only essential data
  const posts = elements.map(post => {
    const commentary = post.commentary || '';
    const specificContent = post.specificContent || {};
    const shareMediaCategory = specificContent['com.linkedin.ugc.ShareMediaCategory'] || {};
    const media = shareMediaCategory.media || [];

    return {
      id: post.id,
      author: post.author,
      created: post.created?.time,
      lastModified: post.lastModified?.time,
      text: commentary,
      visibility: post.visibility?.['com.linkedin.ugc.MemberNetworkVisibility'],
      lifecycleState: post.lifecycleState,
      media: media.map(m => ({
        status: m.status,
        description: m.description?.text,
        media: m.media,
        title: m.title?.text
      })),
      shareCommentary: post.shareCommentary?.text,
      shareMediaCategory: shareMediaCategory.category
    };
  });

  return {
    organizationName: orgData.organizationName,
    organizationId: orgData.organizationId,
    posts: posts,
    count: posts.length,
    start: orgData.start || 0
  };
}
